#!/usr/bin/env python3
"""Harden the bash completion script generated by urfave/cli.

urfave/cli v3.14.0's bash_autocomplete template builds the completion request
as a flattened string and runs it through `eval`. Because COMP_WORDS is
attacker-controlled (it is whatever the user has typed on the command line),
a word such as `x; touch /tmp/pwned` is executed as shell code on TAB.

The checked-in completions/otter.bash uses an argv array instead. This script
re-applies that transformation after `otter completion bash` regenerates the
file, so `make completions` cannot silently reintroduce the eval injection.

Usage: harden-bash-completion.py PATH/TO/otter.bash
"""

from __future__ import annotations

import sys
from pathlib import Path

BUILD_FN = '''__otter_build_completion_request() {
  local -a words_before_cursor=("${COMP_WORDS[@]:0:${COMP_CWORD}}")
  local current_word="${COMP_WORDS[COMP_CWORD]}"

  if [[ "${current_word}" == "-"* ]]; then
    printf '%s %s --generate-shell-completion' "${words_before_cursor[*]}" "${current_word}"
  else
    printf '%s --generate-shell-completion' "${words_before_cursor[*]}"
  fi
}

'''

OLD_LOCAL = "    local request_comp\n"
OLD_EVAL = '''    request_comp="$(__otter_build_completion_request)"
    opts=$(eval "${request_comp}" 2>/dev/null)
'''

NEW_EVAL = '''    # Build the completion request as an argv array. Flattening into a
    # string and eval-ing it re-parses quoted words as shell syntax, so a
    # container name like "x; touch /tmp/pwned" would execute on TAB.
    local -a request=("${words[@]:0:${cword}}")
    [[ "${cur}" == -* ]] && request+=("${cur}")
    request+=("--generate-shell-completion")
    opts=$("${request[@]}" 2>/dev/null)
'''

SAFE_MARKER = 'local -a request=("${words[@]:0:${cword}}")'
SHELLCHECK_HEADER = "# shellcheck disable=all\n"


def harden(path: Path) -> None:
    text = path.read_text()

    # Idempotent: already hardened.
    if SAFE_MARKER in text and "eval \"${request_comp}\"" not in text:
        if not text.startswith(SHELLCHECK_HEADER):
            path.write_text(SHELLCHECK_HEADER + text)
        return

    problems: list[str] = []
    if BUILD_FN not in text:
        problems.append("__otter_build_completion_request block not found")
    if OLD_LOCAL not in text:
        problems.append("local request_comp declaration not found")
    if OLD_EVAL not in text:
        problems.append("eval request_comp invocation not found")
    if problems:
        raise SystemExit(
            "harden-bash-completion.py: unexpected upstream template:\n  "
            + "\n  ".join(problems)
        )

    text = text.replace(BUILD_FN, "", 1)
    text = text.replace(OLD_LOCAL, "", 1)
    text = text.replace(OLD_EVAL, NEW_EVAL, 1)
    if not text.startswith(SHELLCHECK_HEADER):
        text = SHELLCHECK_HEADER + text
    path.write_text(text)


def main() -> None:
    if len(sys.argv) != 2:
        raise SystemExit("usage: harden-bash-completion.py PATH/TO/otter.bash")
    harden(Path(sys.argv[1]))


if __name__ == "__main__":
    main()
